-- 543: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 5 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_543_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_543_guard;
INSERT INTO _migration_543_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_021' AND NOT (q.topic_id IS 'topic_wassce_p2_math_sta' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the median of the data set 3, 5, 8, 10, 12 and 15.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 9","B. 8","C. 10","D. 8.8"]' AND q.correct_answer IS 'A' AND q.explanation IS 'With six ordered values the median is the mean of the third and fourth: (8 + 10) ÷ 2 = 9. (8 or 10 alone forgets to average the two middle values.) Therefore the correct answer is A: 9.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_021' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_543_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_022' AND NOT (q.topic_id IS 'topic_wassce_p2_math_sta' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The mean of six numbers is 7. Five of the numbers add up to 30. Find the sixth number.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6","B. 12","C. 7","D. 5"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The six numbers total 6 × 7 = 42. The five known numbers total 30, so the sixth number is 42 − 30 = 12. (6 is the mean of the five known numbers, 30 ÷ 5.) Therefore the correct answer is B: 12.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_022' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_543_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_023' AND NOT (q.topic_id IS 'topic_wassce_p2_math_sta' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In a frequency table, the value 1 occurs 2 times, the value 2 occurs 3 times and the value 3 occurs 5 times. Calculate the mean of the data.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 2","B. 2.5","C. 2.3","D. 3"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Total of values = (1 × 2) + (2 × 3) + (3 × 5) = 2 + 6 + 15 = 23. Total frequency = 2 + 3 + 5 = 10. Mean = 23 ÷ 10 = 2.3. (2 is the mean of the values 1, 2, 3 ignoring their frequencies.) Therefore the correct answer is C: 2.3.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_023' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_543_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_024' AND NOT (q.topic_id IS 'topic_wassce_p2_math_sta' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The mean of the numbers 2, 5, x and 9 is 6. Find the value of x.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 4","B. 10","C. 7","D. 8"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The four numbers total 4 × 6 = 24. The three known numbers total 2 + 5 + 9 = 16, so x = 24 − 16 = 8. (4 wrongly divides 16 by 4 instead of subtracting from 24.) Therefore the correct answer is D: 8.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_024' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_543_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_025' AND NOT (q.topic_id IS 'topic_wassce_p2_math_qdr' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Write down the roots of the equation (x − 4)(x + 1) = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 4 or x = −1","B. x = −4 or x = 1","C. x = 4 or x = 1","D. x = −4 or x = −1"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A product is zero only when a factor is zero: x − 4 = 0 gives x = 4, and x + 1 = 0 gives x = −1. (x = −4 or x = 1 reverses both signs.) Therefore the correct answer is A: x = 4 or x = −1.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write down' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_025' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_021', 'topic_wassce_p2_math_sta', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the median of the data set 3, 5, 8, 10, 12 and 15.', 'multiple_choice', NULL, '["A. 9","B. 8","C. 10","D. 8.8"]', 'A', 'With six ordered values the median is the mean of the third and fourth: (8 + 10) ÷ 2 = 9. (8 or 10 alone forgets to average the two middle values.) Therefore the correct answer is A: 9.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
