INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_023', 'topic_wassce_p2_math_sta', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'In a frequency table, the value 1 occurs 2 times, the value 2 occurs 3 times and the value 3 occurs 5 times. Calculate the mean of the data.', 'multiple_choice', NULL, '["A. 2","B. 2.5","C. 2.3","D. 3"]', 'C', 'Total of values = (1 × 2) + (2 × 3) + (3 × 5) = 2 + 6 + 15 = 23. Total frequency = 2 + 3 + 5 = 10. Mean = 23 ÷ 10 = 2.3. (2 is the mean of the values 1, 2, 3 ignoring their frequencies.) Therefore the correct answer is C: 2.3.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_024', 'topic_wassce_p2_math_sta', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The mean of the numbers 2, 5, x and 9 is 6. Find the value of x.', 'multiple_choice', NULL, '["A. 4","B. 10","C. 7","D. 8"]', 'D', 'The four numbers total 4 × 6 = 24. The three known numbers total 2 + 5 + 9 = 16, so x = 24 − 16 = 8. (4 wrongly divides 16 by 4 instead of subtracting from 24.) Therefore the correct answer is D: 8.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
